// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(this));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        vm.prank(actor);
        try c.withdrawAll(address(0)) { } catch { }
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter == balanceBefore);
    }
}
